    private const ROUTES=['/playbill','/playbill/asset','/admin/playbill/media'];
    public static function handles(string $route):bool{return in_array($route,self::ROUTES,true);}
    public static function render(string $route,string $basePath):never
    {
        $db=Database::connect(dirname(__DIR__));
        if($route==='/playbill/asset'){self::asset($db);}
        if($route==='/playbill'){self::publicPage($db,$basePath);}
        Auth::startSession();$user=Auth::currentUser($db);if(!$user||!AccessPolicy::canManagePlaybill($user)){http_response_code(403);exit('Playbill management permission is required.');}$production=ProductionContext::selected($db,$user);if(!$production){header('Location: '.($basePath?:'').'/production',true,303);exit;}$_SESSION['playbill2_csrf']??=bin2hex(random_bytes(24));$playbill=self::playbill($db,(int)$production['id']);if(!$playbill){header('Location: '.($basePath?:'').'/admin/playbill',true,303);exit;}if($_SERVER['REQUEST_METHOD']==='POST')self::post($db,$basePath,$user,$playbill);self::adminPage($db,$basePath,$user,$production,$playbill);
    }
    private static function post(PDO $db,string $basePath,array $user,array $playbill):never
    {
        if(!hash_equals((string)($_SESSION['playbill2_csrf']??''),(string)($_POST['csrf_token']??''))){self::flash('error','Your Playbill session expired.');self::redirect($basePath.'/admin/playbill/media');}try{$action=(string)($_POST['action']??'');if($action==='artwork'){PlaybillEnhancementService::saveArtwork($db,dirname(__DIR__),(int)$playbill['id'],(int)$user['id'],$_FILES['artwork']??[]);self::flash('success','Production artwork updated.');}elseif($action==='create_sponsor'){$id=PlaybillEnhancementService::createSponsor($db,dirname(__DIR__),(int)$user['id'],$_POST,$_FILES['logo']??[]);PlaybillEnhancementService::attachSponsor($db,(int)$playbill['id'],$id,(string)($_POST['placement_label']??''),(int)($_POST['sort_order']??0),(int)$user['id']);self::flash('success','Sponsor created and added to this Playbill.');}elseif($action==='attach_sponsor'){$sid=filter_input(INPUT_POST,'sponsor_id',FILTER_VALIDATE_INT)?:0;PlaybillEnhancementService::attachSponsor($db,(int)$playbill['id'],(int)$sid,(string)($_POST['placement_label']??''),(int)($_POST['sort_order']??0),(int)$user['id']);self::flash('success','Sponsor added to this Playbill.');}else throw new RuntimeException('Choose a valid Playbill media action.');}catch(RuntimeException $e){self::flash('error',$e->getMessage());}self::redirect($basePath.'/admin/playbill/media');
    }
    private static function adminPage(PDO $db,string $basePath,array $user,array $production,array $playbill):never
    {
        $sponsors=PlaybillEnhancementService::sponsors($db,(int)$playbill['id']);$library=PlaybillEnhancementService::sponsorLibrary($db);$cast=PlaybillEnhancementService::castProfiles($db,(int)$production['id']);$u=static fn(string $p):string=>($basePath?:'').$p;$e=static fn(string $v):string=>htmlspecialchars($v,ENT_QUOTES,'UTF-8');$flash=self::takeFlash();header('Content-Type:text/html; charset=utf-8');?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Playbill Media · CTSMD Connect</title><link rel="stylesheet" href="<?=$u('/assets/css/app.css')?>"><link rel="stylesheet" href="<?=$u('/assets/css/unified-navigation.css')?>"><link rel="stylesheet" href="<?=$u('/assets/css/playbill2.css')?>"></head><body class="app-body"><div class="unified-shell"><?php AppNavigation::renderSidebar('/admin/playbill',$basePath,$user);?><main class="unified-main"><?php AppNavigation::renderHeader('Production','Playbill Media & Sponsors',$basePath,[['label'=>'Playbill editor','href'=>'/admin/playbill','active'=>false],['label'=>'Media & sponsors','href'=>'/admin/playbill/media','active'=>true]]);?><div class="pb2-admin"><?php if($flash):?><div class="pb2-flash <?=$e($flash['type'])?>"><?=$e($flash['message'])?></div><?php endif;?><section class="pb2-hero"><small><?=$e(strtoupper((string)$production['title']))?></small><h2>Give the program a face.</h2><p>Artwork, Student theatre profiles, and reusable sponsors feed the public Playbill without duplicating cast data.</p></section><div class="pb2-grid"><section class="pb2-card"><h3>Production artwork</h3><?php if($playbill['artwork_stored_file_id']&&$playbill['public_slug']):?><img class="pb2-art-preview" src="<?=$u('/playbill/asset?slug='.urlencode((string)$playbill['public_slug']).'&kind=artwork&id=0')?>" alt="Current production artwork"><?php endif;?><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['playbill2_csrf'])?>"><input type="hidden" name="action" value="artwork"><label>Artwork image<input type="file" name="artwork" accept="image/jpeg,image/png,image/webp" required></label><button class="button" type="submit">Upload artwork</button></form></section><section class="pb2-card"><h3>Cast profile readiness</h3><p><?=count($cast)?> available Student cast profiles feed the Playbill.</p><?php foreach($cast as $member):?><div class="pb2-readiness"><span><b><?=$e((string)$member['display_name'])?></b><small><?=$e((string)$member['participation_role'])?></small></span><em><?=$member['headshot_stored_file_id']?'Headshot ✓':'No headshot'?> · <?=$member['short_bio']?'Bio ✓':'No bio'?></em></div><?php endforeach;?></section><section class="pb2-card"><h3>Add existing sponsor</h3><form method="post"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['playbill2_csrf'])?>"><input type="hidden" name="action" value="attach_sponsor"><label>Sponsor<select name="sponsor_id" required><?php foreach($library as $s):?><option value="<?=(int)$s['id']?>"><?=$e((string)$s['name'])?></option><?php endforeach;?></select></label><label>Placement label<input name="placement_label" maxlength="100" placeholder="Presenting Sponsor"></label><label>Order<input type="number" name="sort_order" value="10"></label><button class="button" type="submit">Add to Playbill</button></form></section><section class="pb2-card"><h3>Create reusable sponsor</h3><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['playbill2_csrf'])?>"><input type="hidden" name="action" value="create_sponsor"><label>Name<input name="sponsor_name" maxlength="190" required></label><label>Website<input type="url" name="website_url" maxlength="1000"></label><label>Blurb<textarea name="blurb" maxlength="500" rows="3"></textarea></label><label>Logo<input type="file" name="logo" accept="image/jpeg,image/png,image/webp"></label><label>Placement label<input name="placement_label" maxlength="100"></label><label>Order<input type="number" name="sort_order" value="10"></label><button class="button" type="submit">Create & add sponsor</button></form></section></div><section class="pb2-card"><h3>Sponsors on this Playbill</h3><div class="pb2-sponsors-admin"><?php foreach($sponsors as $s):?><article><b><?=$e((string)$s['name'])?></b><span><?=$e((string)($s['placement_label']?:'Sponsor'))?></span></article><?php endforeach;?><?php if(!$sponsors):?><p>No sponsors added yet.</p><?php endif;?></div></section></div></main></div><script src="<?=$u('/assets/js/unified-navigation.js')?>"></script></body></html><?php exit;
    }
    private static function publicPage(PDO $db,string $basePath):never
    {
        $slug=trim((string)($_GET['slug']??''));$playbill=self::publicPlaybill($db,$slug);if(!$playbill){http_response_code(404);self::publicRender($basePath,null,[],[],[],[]);}$sections=self::sections($db,(int)$playbill['id']);$cast=PlaybillEnhancementService::castProfiles($db,(int)$playbill['production_id']);$staff=self::staff($db,(int)$playbill['production_id']);$sponsors=PlaybillEnhancementService::sponsors($db,(int)$playbill['id']);self::publicRender($basePath,$playbill,$sections,$cast,$staff,$sponsors);
    }
    private static function publicRender(string $basePath,?array $pb,array $sections,array $cast,array $staff,array $sponsors):never
    {
        $u=static fn(string $p):string=>($basePath?:'').$p;$e=static fn(string $v):string=>htmlspecialchars($v,ENT_QUOTES,'UTF-8');header('Content-Type:text/html; charset=utf-8');?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=$pb?$e((string)($pb['display_title']?:$pb['production_title'])):'Playbill not found'?> · CTSMD</title><link rel="stylesheet" href="<?=$u('/assets/css/playbill2.css')?>"></head><body class="pb2-public"><?php if(!$pb):?><main class="pb2-public-main"><h1>Playbill not found.</h1></main><?php else:?><header class="pb2-top"><b>CTSMD</b><span>PLAYBILL</span><button onclick="window.print()">Print</button></header><main class="pb2-public-main"><section class="pb2-cover"><?php if($pb['artwork_stored_file_id']):?><img src="<?=$u('/playbill/asset?slug='.urlencode((string)$pb['public_slug']).'&kind=artwork&id=0')?>" alt="<?=$e((string)$pb['display_title'])?> artwork"><?php endif;?><div><small>CHILDREN’S THEATRE OF SOUTHERN MARYLAND</small><h1><?=$e((string)($pb['display_title']?:$pb['production_title']))?></h1><h2><?=$e((string)($pb['subtitle']?:$pb['season']))?></h2><p><?=$e((string)$pb['cover_note'])?></p></div></section><section class="pb2-section"><small>CAST</small><h2>Company</h2><div class="pb2-cast"><?php foreach($cast as $member):?><article><?php if($member['headshot_stored_file_id']):?><img src="<?=$u('/playbill/asset?slug='.urlencode((string)$pb['public_slug']).'&kind=headshot&id='.(int)$member['user_id'])?>" alt="<?=$e((string)$member['display_name'])?> headshot"><?php endif;?><div><h3><?=$e((string)$member['display_name'])?></h3><b><?=$e((string)$member['participation_role'])?></b><?php if($member['short_bio']):?><p><?=$e((string)$member['short_bio'])?></p><?php endif;?></div></article><?php endforeach;?></div></section><section class="pb2-section"><small>PRODUCTION TEAM</small><h2>Behind the curtain</h2><div class="pb2-team"><?php foreach($staff as $member):?><div><b><?=$e((string)$member['name'])?></b><span><?=$e((string)$member['participation_role'])?></span></div><?php endforeach;?></div></section><?php foreach($sections as $section):?><section class="pb2-section copy"><small><?=$e(strtoupper(str_replace('_',' ',(string)$section['section_type'])))?></small><h2><?=$e((string)$section['heading'])?></h2><p><?=nl2br($e((string)$section['body']))?></p></section><?php endforeach;?><?php if($sponsors):?><section class="pb2-section"><small>WITH THANKS TO</small><h2>Our Sponsors</h2><div class="pb2-sponsors"><?php foreach($sponsors as $s):?><article><?php if($s['logo_stored_file_id']):?><img src="<?=$u('/playbill/asset?slug='.urlencode((string)$pb['public_slug']).'&kind=sponsor&id='.(int)$s['id'])?>" alt="<?=$e((string)$s['name'])?> logo"><?php endif;?><b><?=$e((string)$s['name'])?></b><span><?=$e((string)($s['placement_label']?:''))?></span><?php if($s['blurb']):?><p><?=$e((string)$s['blurb'])?></p><?php endif;?></article><?php endforeach;?></div></section><?php endif;?></main><footer class="pb2-footer">Children’s Theatre of Southern Maryland · Digital Playbill</footer><?php endif;?></body></html><?php exit;
    }
    private static function asset(PDO $db):never{$slug=(string)($_GET['slug']??'');$kind=(string)($_GET['kind']??'');$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;$version=PlaybillEnhancementService::publicAsset($db,$slug,$kind,(int)$id);if(!$version){http_response_code(404);exit('Asset unavailable.');}StorageService::stream(dirname(__DIR__),$version,false);}
    private static function playbill(PDO $db,int $production):?array{$s=$db->prepare('SELECT pb.*,p.title production_title,p.season FROM playbills pb JOIN productions p ON p.id=pb.production_id WHERE pb.production_id=:p ORDER BY pb.id DESC LIMIT 1');$s->execute(['p'=>$production]);return$s->fetch()?:null;}
    private static function publicPlaybill(PDO $db,string $slug):?array{$s=$db->prepare("SELECT pb.*,p.title production_title,p.season FROM playbills pb JOIN productions p ON p.id=pb.production_id WHERE pb.public_slug=:slug AND pb.status='current' LIMIT 1");$s->execute(['slug'=>$slug]);return$s->fetch()?:null;}
    private static function sections(PDO $db,int $id):array{$s=$db->prepare('SELECT * FROM playbill_sections WHERE playbill_id=:id AND active=1 ORDER BY sort_order,id');$s->execute(['id'=>$id]);return$s->fetchAll();}
    private static function staff(PDO $db,int $production):array{$s=$db->prepare("SELECT CONCAT(u.first_name,' ',u.last_name) name,pm.participation_role FROM production_memberships pm JOIN users u ON u.id=pm.user_id AND u.active=1 AND u.account_status<>'disabled' WHERE pm.production_id=:p AND pm.status='active' AND pm.audience_type='staff' ORDER BY pm.participation_role,u.last_name,u.first_name");$s->execute(['p'=>$production]);return$s->fetchAll();}
    private static function flash(string $t,string $m):void{$_SESSION['pb2_flash']=['type'=>$t,'message'=>$m];}private static function takeFlash():?array{$v=$_SESSION['pb2_flash']??null;unset($_SESSION['pb2_flash']);return is_array($v)?$v:null;}private static function redirect(string $url):never{header('Location: '.$url,true,303);exit;}
}